script="from pathlib import Path\nimport tempfile,shutil,base64,subprocess,json\nfiles=FILES\nwith tempfile.TemporaryDirectory(prefix='group-reader-test-') as d:\n root=Path(d);base=Path('/opt/preclass/current/backend');shutil.copytree(base/'dist',root/'dist');shutil.copy(base/'package.json',root/'package.json');(root/'node_modules').symlink_to(base/'node_modules',target_is_directory=True);p=root/'dist/backend/src'\n for name,data in files.items():\n  target=(root/name) if name.endswith('.pdf') else p/name.replace('.after.js','.js');target.write_bytes(base64.b64decode(data))\n results={}\n for name in ['legacy-test.mjs','activity-test.mjs','backend-transfer-test.mjs','backend-reader-test.mjs']:\n  result=subprocess.run(['/opt/preclass/runtime/node/bin/node',str(p/name)],cwd=d,capture_output=True,text=True);assert result.returncode==0,name+' '+result.stderr;results[name]=json.loads(result.stdout.strip())\n print(json.dumps({'passed':True,'isolatedMemoryDatabase':True,'productionWrites':False,'results':results}))\n".replace('FILES',repr(files))
r=subprocess.run(ssh+['python3','-'],input=script.encode(),capture_output=True,timeout=60);print(r.stdout.decode());print(r.stderr.decode());assert r.returncode==0
